echo '✅ panels/sanei.py بازنویسی شد'

echo "🔎 بررسی سینتکس فایل‌ها..."
for f in bot/handlers/admin.py bot/handlers/user.py bot/keyboards.py bot/middlewares.py bot/main.py database/crud.py database/db.py panels/sanei.py; do
  python3 -c "import ast; ast.parse(open('/opt/vpnbot/$f').read())" && echo "✅ $f سالم است" || echo "❌ خطای سینتکس در $f !!"
done

echo "🗄  بروزرسانی دیتابیس (ستون‌های جدید در صورت نیاز)..."
python3 << 'DBFIX'
import sqlite3
con = sqlite3.connect("/opt/vpnbot/vpnbot.db")
cur = con.cursor()

def ensure_column(table, col, coltype):
    cur.execute(f"PRAGMA table_info({table})")
    cols = [r[1] for r in cur.fetchall()]
    if col not in cols:
        cur.execute(f"ALTER TABLE {table} ADD COLUMN {col} {coltype}")
        print(f"✅ ستون {table}.{col} اضافه شد")
    else:
        print(f"⏭️  ستون {table}.{col} از قبل وجود دارد")

ensure_column("discount_codes", "expires_at", "DATETIME")
ensure_column("services", "panel_removed", "BOOLEAN DEFAULT 0")
ensure_column("users", "phone", "VARCHAR(20)")
ensure_column("users", "phone_exempt", "BOOLEAN DEFAULT 0")

con.commit()
con.close()
DBFIX

echo "🧹 پاک‌کردن __pycache__..."
find /opt/vpnbot -type d -name "__pycache__" -exec rm -rf {} + 2>/dev/null

echo "🔄 ری‌استارت سرویس..."
systemctl restart vpnbot
sleep 2
journalctl -u vpnbot -n 25 --no-pager
